import csv
import json
import os
from pyscipopt import Model, quicksum

BASE = "/app"
DATA = os.path.join(BASE, "data")
SUB = os.path.join(BASE, "submissions")
os.makedirs(SUB, exist_ok=True)

# ---------------- Load data ----------------
with open(os.path.join(DATA, "config.json")) as f:
    cfg = json.load(f)
CARBON_PRICE = cfg["carbon_price_per_kg"]
CARBON_CAP = cfg["carbon_cap_kg"]

markets = {}
with open(os.path.join(DATA, "markets.csv")) as f:
    for row in csv.DictReader(f):
        m = row["market_id"]
        markets[m] = {
            "lfp": float(row["lfp_packs"]),
            "nmc": float(row["nmc_packs"]),
            "dam_lfp": float(row["damaged_lfp_share"]),
            "dam_nmc": float(row["damaged_nmc_share"]),
            "trace": float(row["traceability_score"]),
            "min_audit": float(row["min_audited_test_share"]),
        }

hubs = {}
with open(os.path.join(DATA, "collection_hubs.csv")) as f:
    for row in csv.DictReader(f):
        c = row["hub_id"]
        hubs[c] = {
            "fixed": float(row["fixed_cost"]),
            "fixed_em": float(row["fixed_emission_kg"]),
            "cap": float(row["capacity_packs"]),
            "min": float(row["min_throughput_if_open"]),
            "hcost": float(row["handling_cost_per_pack"]),
            "hem": float(row["handling_emission_kg_per_pack"]),
            "nmc": int(row["nmc_certified"]),
        }

tests = {}
with open(os.path.join(DATA, "testing_centers.csv")) as f:
    for row in csv.DictReader(f):
        t = row["test_id"]
        tests[t] = {
            "fixed": float(row["fixed_cost"]),
            "fixed_em": float(row["fixed_emission_kg"]),
            "cap": float(row["capacity_packs"]),
            "min": float(row["min_throughput_if_open"]),
            "tcost": float(row["test_cost_per_pack"]),
            "tem": float(row["test_emission_kg_per_pack"]),
            "audit": int(row["audit_upgrade"]),
            "reman": int(row["reman_certified"]),
        }

outlets = {}
with open(os.path.join(DATA, "outlets.csv")) as f:
    for row in csv.DictReader(f):
        o = row["outlet_id"]
        outlets[o] = {
            "type": row["outlet_type"],
            "tech": row["technology"],
            "cap": float(row["capacity_packs"]),
            "pc_lfp": float(row["processing_cost_lfp"]),
            "pc_nmc": float(row["processing_cost_nmc"]),
            "rv_lfp": float(row["recovered_value_lfp"]),
            "rv_nmc": float(row["recovered_value_nmc"]),
            "pe_lfp": float(row["processing_emission_lfp"]),
            "pe_nmc": float(row["processing_emission_nmc"]),
            "lfp": int(row["lfp_allowed"]),
            "nmc": int(row["nmc_allowed"]),
        }

policy = {}
with open(os.path.join(DATA, "policy_rules.csv")) as f:
    for row in csv.DictReader(f):
        c = row["chemistry"]
        policy[c] = {
            "hv": float(row["min_high_value_share"]),
            "sl": float(row["min_second_life_share"]),
            "rec": float(row["min_recycle_share"]),
            "disp": float(row["max_disposal_share"]),
            "hydro": float(row["min_hydromet_share_of_recycling"]),
            "pyro": float(row["max_pyromet_share_of_recycling"]),
        }

lanes = []
with open(os.path.join(DATA, "lanes.csv")) as f:
    for row in csv.DictReader(f):
        lanes.append({
            "id": row["lane_id"],
            "stage": row["stage"],
            "from": row["from_id"],
            "to": row["to_id"],
            "dist": float(row["distance_km"]),
            "cap": float(row["capacity_packs"]),
            "cpk": float(row["cost_per_pack_km"]),
            "epk": float(row["emission_kg_per_pack_km"]),
            "lfp": int(row["lfp_allowed"]),
            "nmc": int(row["nmc_allowed"]),
        })

CHEMS = ["lfp", "nmc"]
MARKETS = sorted(markets.keys())
HUBS = sorted(hubs.keys())
TESTS = sorted(tests.keys())
OUTLETS = sorted(outlets.keys())

lanes_m2h = [l for l in lanes if l["stage"] == "market_to_hub"]
lanes_h2t = [l for l in lanes if l["stage"] == "hub_to_test"]
lanes_t2o = [l for l in lanes if l["stage"] == "test_to_outlet"]
lane_by_id = {l["id"]: l for l in lanes}

# ---------------- Build model ----------------
model = Model("ev_battery_recycling")
model.setParam("gaprel", 0.0005)

time_limit = 300.0
env_limit = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
if env_limit is not None:
    try:
        time_limit = min(time_limit, float(env_limit))
    except ValueError:
        pass
model.setParam("limits/time", time_limit)

# Open variables
y = {}
for c in HUBS:
    y[c] = model.addVar(name=f"y_{c}", vtype="B", lb=0, ub=1, obj=0.0)
z = {}
for t in TESTS:
    z[t] = model.addVar(name=f"z_{t}", vtype="B", lb=0, ub=1, obj=0.0)

def lane_allows(l, chem):
    return (chem == "lfp" and l["lfp"]) or (chem == "nmc" and l["nmc"])

# Flow variables
f1 = {}
for l in lanes_m2h:
    m = l["from"]
    for chem in CHEMS:
        if lane_allows(l, chem):
            f1[(m, chem, l["id"])] = model.addVar(
                name=f"f1_{m}_{chem}_{l['id']}", vtype="C", lb=0, ub=None, obj=0.0)

f2 = {}
for l in lanes_h2t:
    for m in MARKETS:
        for chem in CHEMS:
            if lane_allows(l, chem):
                f2[(m, chem, l["id"])] = model.addVar(
                    name=f"f2_{m}_{chem}_{l['id']}", vtype="C", lb=0, ub=None, obj=0.0)

f3 = {}
for l in lanes_t2o:
    o = l["to"]
    for m in MARKETS:
        for chem in CHEMS:
            if lane_allows(l, chem):
                allowed = outlets[o]["lfp"] if chem == "lfp" else outlets[o]["nmc"]
                if allowed:
                    f3[(m, chem, l["id"])] = model.addVar(
                        name=f"f3_{m}_{chem}_{l['id']}", vtype="C", lb=0, ub=None, obj=0.0)

# ---------------- Objective coefficients (tracked manually) ----------------
obj_terms = []
emission_terms = []

for c in HUBS:
    obj_terms.append((hubs[c]["fixed"], y[c]))
    emission_terms.append((hubs[c]["fixed_em"], y[c]))
for t in TESTS:
    obj_terms.append((tests[t]["fixed"], z[t]))
    emission_terms.append((tests[t]["fixed_em"], z[t]))

for (m, chem, lid), var in f1.items():
    l = lane_by_id[lid]
    obj_terms.append((l["dist"] * l["cpk"], var))
    emission_terms.append((l["dist"] * l["epk"], var))

for (m, chem, lid), var in f2.items():
    l = lane_by_id[lid]
    obj_terms.append((l["dist"] * l["cpk"], var))
    emission_terms.append((l["dist"] * l["epk"], var))

for (m, chem, lid), var in f3.items():
    l = lane_by_id[lid]
    o = l["to"]
    od = outlets[o]
    pc = od["pc_lfp"] if chem == "lfp" else od["pc_nmc"]
    rv = od["rv_lfp"] if chem == "lfp" else od["rv_nmc"]
    pe = od["pe_lfp"] if chem == "lfp" else od["pe_nmc"]
    obj_terms.append((l["dist"] * l["cpk"] + pc - rv, var))
    emission_terms.append((l["dist"] * l["epk"] + pe, var))

for c in HUBS:
    hd = hubs[c]
    for (m, chem, lid), var in f1.items():
        if lane_by_id[lid]["to"] == c:
            obj_terms.append((hd["hcost"], var))
            emission_terms.append((hd["hem"], var))

for t in TESTS:
    td = tests[t]
    for (m, chem, lid), var in f2.items():
        if lane_by_id[lid]["to"] == t:
            obj_terms.append((td["tcost"], var))
            emission_terms.append((td["tem"], var))

# ---------------- Constraints ----------------
# 1. Demand routing
for m in MARKETS:
    for chem in CHEMS:
        d = markets[m][chem]
        cons = quicksum([var for (mm, cc, lid), var in f1.items() if mm == m and cc == chem])
        model.addCons(cons == d, name=f"demand_{m}_{chem}")

# 2a. Conservation at hubs
for c in HUBS:
    for m in MARKETS:
        for chem in CHEMS:
            vin = quicksum([var for (mm, cc, lid), var in f1.items()
                            if mm == m and cc == chem and lane_by_id[lid]["to"] == c])
            vout = quicksum([var for (mm, cc, lid), var in f2.items()
                             if mm == m and cc == chem and lane_by_id[lid]["from"] == c])
            model.addCons(vin == vout, name=f"cons_hub_{c}_{m}_{chem}")

# 2b. Conservation at tests
for t in TESTS:
    for m in MARKETS:
        for chem in CHEMS:
            vin = quicksum([var for (mm, cc, lid), var in f2.items()
                            if mm == m and cc == chem and lane_by_id[lid]["to"] == t])
            vout = quicksum([var for (mm, cc, lid), var in f3.items()
                             if mm == m and cc == chem and lane_by_id[lid]["from"] == t])
            model.addCons(vin == vout, name=f"cons_test_{t}_{m}_{chem}")

# 3. Open linkage (max capacity)
for c in HUBS:
    total_in = quicksum([var for (m, chem, lid), var in f1.items() if lane_by_id[lid]["to"] == c])
    model.addCons(total_in <= hubs[c]["cap"] * y[c], name=f"cap_hub_{c}")
for t in TESTS:
    total_in = quicksum([var for (m, chem, lid), var in f2.items() if lane_by_id[lid]["to"] == t])
    model.addCons(total_in <= tests[t]["cap"] * z[t], name=f"cap_test_{t}")

# 4. Min throughput
for c in HUBS:
    total_in = quicksum([var for (m, chem, lid), var in f1.items() if lane_by_id[lid]["to"] == c])
    model.addCons(total_in >= hubs[c]["min"] * y[c], name=f"min_hub_{c}")
for t in TESTS:
    total_in = quicksum([var for (m, chem, lid), var in f2.items() if lane_by_id[lid]["to"] == t])
    model.addCons(total_in >= tests[t]["min"] * z[t], name=f"min_test_{t}")

# 5. Hub NMC certification: NMC flow into non-certified hub = 0
for c in HUBS:
    if hubs[c]["nmc"] == 0:
        for (m, chem, lid), var in f1.items():
            if chem == "nmc" and lane_by_id[lid]["to"] == c:
                model.addCons(var == 0, name=f"nmc_cert_{c}_{m}_{lid}")

# 6. Lane capacities
for l in lanes_m2h:
    cons = quicksum([var for (m, chem, lid), var in f1.items() if lid == l["id"]])
    model.addCons(cons <= l["cap"], name=f"lane_{l['id']}")
for l in lanes_h2t:
    cons = quicksum([var for (m, chem, lid), var in f2.items() if lid == l["id"]])
    model.addCons(cons <= l["cap"], name=f"lane_{l['id']}")
for l in lanes_t2o:
    cons = quicksum([var for (m, chem, lid), var in f3.items() if lid == l["id"]])
    model.addCons(cons <= l["cap"], name=f"lane_{l['id']}")

# 8. Reman certification: non-reman-certified test cannot send to remanufacturing
reman_outlets = [o for o in OUTLETS if outlets[o]["type"] == "remanufacturing"]
for t in TESTS:
    if tests[t]["reman"] == 0:
        for o in reman_outlets:
            for (m, chem, lid), var in f3.items():
                l = lane_by_id[lid]
                if l["from"] == t and l["to"] == o:
                    model.addCons(var == 0, name=f"reman_cert_{t}_{o}_{m}_{chem}")

# 9. Traceability: low-trace markets (<0.75) to reman only via audit-upgrade tests
low_trace = [m for m in MARKETS if markets[m]["trace"] < 0.75]
for m in low_trace:
    for t in TESTS:
        if tests[t]["audit"] == 0:
            for o in reman_outlets:
                for (mm, chem, lid), var in f3.items():
                    l = lane_by_id[lid]
                    if mm == m and l["from"] == t and l["to"] == o:
                        model.addCons(var == 0, name=f"audit_{m}_{t}_{o}_{chem}")

# 10. Audited-test share per market
for m in MARKETS:
    a = markets[m]["min_audit"]
    if a > 0:
        total = sum(markets[m][chem] for chem in CHEMS)
        audited = quicksum([var for (mm, chem, lid), var in f2.items()
                            if mm == m and tests[lane_by_id[lid]["to"]]["audit"] == 1])
        model.addCons(audited >= a * total, name=f"audit_share_{m}")

# 11. Damaged share: high-value (reman + second-life) per market/chem
hv_outlets = [o for o in OUTLETS if outlets[o]["type"] in ("remanufacturing", "second_life")]
for m in MARKETS:
    for chem in CHEMS:
        d = markets[m][chem]
        dam = markets[m]["dam_lfp"] if chem == "lfp" else markets[m]["dam_nmc"]
        hv = quicksum([var for (mm, cc, lid), var in f3.items()
                       if mm == m and cc == chem and lane_by_id[lid]["to"] in hv_outlets])
        model.addCons(hv <= (1.0 - dam) * d, name=f"damaged_{m}_{chem}")

# 12. Outlet TOTAL capacity (both chemistries combined) + chemistry eligibility
for o in OUTLETS:
    od = outlets[o]
    cons = quicksum([var for (m, cc, lid), var in f3.items()
                     if lane_by_id[lid]["to"] == o])
    model.addCons(cons <= od["cap"], name=f"outlet_cap_{o}")

# 13. Policy shares per chemistry
recycler_outlets = [o for o in OUTLETS if outlets[o]["type"] == "recycler"]
sl_outlets = [o for o in OUTLETS if outlets[o]["type"] == "second_life"]
disp_outlets = [o for o in OUTLETS if outlets[o]["type"] == "disposal"]
hydro_outlets = [o for o in recycler_outlets if "hydro" in outlets[o]["tech"]]
pyro_outlets = [o for o in recycler_outlets if "pyro" in outlets[o]["tech"]]

for chem in CHEMS:
    p = policy[chem]
    total_c = sum(markets[m][chem] for m in MARKETS)
    hv = quicksum([var for (m, cc, lid), var in f3.items()
                   if cc == chem and lane_by_id[lid]["to"] in hv_outlets])
    sl = quicksum([var for (m, cc, lid), var in f3.items()
                   if cc == chem and lane_by_id[lid]["to"] in sl_outlets])
    rec = quicksum([var for (m, cc, lid), var in f3.items()
                    if cc == chem and lane_by_id[lid]["to"] in recycler_outlets])
    disp = quicksum([var for (m, cc, lid), var in f3.items()
                     if cc == chem and lane_by_id[lid]["to"] in disp_outlets])
    hydro = quicksum([var for (m, cc, lid), var in f3.items()
                      if cc == chem and lane_by_id[lid]["to"] in hydro_outlets])
    pyro = quicksum([var for (m, cc, lid), var in f3.items()
                     if cc == chem and lane_by_id[lid]["to"] in pyro_outlets])

    model.addCons(hv >= p["hv"] * total_c, name=f"pol_hv_{chem}")
    model.addCons(sl >= p["sl"] * total_c, name=f"pol_sl_{chem}")
    model.addCons(rec >= p["rec"] * total_c, name=f"pol_rec_{chem}")
    model.addCons(disp <= p["disp"] * total_c, name=f"pol_disp_{chem}")
    # KEY FIX: hydromet floor is a share of TOTAL chemistry flow, not of recycling flow.
    model.addCons(hydro >= p["hydro"] * total_c, name=f"pol_hydro_{chem}")
    model.addCons(pyro <= p["pyro"] * rec, name=f"pol_pyro_{chem}")

# 14. Carbon cap
total_emission = quicksum([(coef * var) for (coef, var) in emission_terms])
model.addCons(total_emission <= CARBON_CAP, name="carbon_cap")

# ---------------- Objective ----------------
obj_expr = quicksum([(coef * var) for (coef, var) in obj_terms]) + CARBON_PRICE * total_emission
model.setObjective(obj_expr, sense="minimize")

# ---------------- Solve ----------------
status = "unknown"
objval = None
try:
    model.optimize()
    status = model.getStatus()
    if model.getNSols() > 0:
        objval = model.getObjVal()
except Exception as e:
    print(f"Solver error: {e}")
    status = "error"

# ---------------- Extract solution ----------------
sol_rows = []

def getval(var):
    try:
        return model.getVal(var)
    except Exception:
        return 0.0

opened_hubs = []
opened_tests = []
for c in HUBS:
    if getval(y[c]) > 0.5:
        opened_hubs.append(c)
for t in TESTS:
    if getval(z[t]) > 0.5:
        opened_tests.append(t)

for c in opened_hubs:
    sol_rows.append(["open", "collection_hub", c, "", "", "", "1"])
for t in opened_tests:
    sol_rows.append(["open", "testing_center", t, "", "", "", "1"])

EPS = 1e-6
for (m, chem, lid), var in f1.items():
    q = getval(var)
    if q > EPS:
        l = lane_by_id[lid]
        sol_rows.append(["flow", "market_to_hub", m, l["to"], m, chem, f"{q:.8f}"])
for (m, chem, lid), var in f2.items():
    q = getval(var)
    if q > EPS:
        l = lane_by_id[lid]
        sol_rows.append(["flow", "hub_to_test", l["from"], l["to"], m, chem, f"{q:.8f}"])
for (m, chem, lid), var in f3.items():
    q = getval(var)
    if q > EPS:
        l = lane_by_id[lid]
        sol_rows.append(["flow", "test_to_outlet", l["from"], l["to"], m, chem, f"{q:.8f}"])

sol_path = os.path.join(SUB, "solution.csv")
with open(sol_path, "w", newline="") as f:
    w = csv.writer(f)
    w.writerow(["record_type", "stage", "origin_id", "destination_id", "market_id", "chemistry", "quantity"])
    for r in sol_rows:
        w.writerow(r)

# ---------------- Validation ----------------
print(f"Solver status: {status}")
print(f"Objective: {objval}")
print(f"Opened hubs: {opened_hubs}")
print(f"Opened tests: {opened_tests}")
print(f"Flow rows: {len(sol_rows) - len(opened_hubs) - len(opened_tests)}")

ok = True
for m in MARKETS:
    for chem in CHEMS:
        routed = sum(getval(var) for (mm, cc, lid), var in f1.items() if mm == m and cc == chem)
        d = markets[m][chem]
        if abs(routed - d) > 1e-4:
            ok = False
            print(f"DEMAND FAIL {m} {chem}: routed={routed} demand={d}")
print("Demand routing OK" if ok else "Demand routing FAILED")

# Conservation check
ok = True
for c in HUBS:
    for m in MARKETS:
        for chem in CHEMS:
            vin = sum(getval(var) for (mm, cc, lid), var in f1.items()
                      if mm == m and cc == chem and lane_by_id[lid]["to"] == c)
            vout = sum(getval(var) for (mm, cc, lid), var in f2.items()
                       if mm == m and cc == chem and lane_by_id[lid]["from"] == c)
            if abs(vin - vout) > 1e-4:
                ok = False
                print(f"CONSERVATION HUB FAIL {c} {m} {chem}: in={vin} out={vout}")
for t in TESTS:
    for m in MARKETS:
        for chem in CHEMS:
            vin = sum(getval(var) for (mm, cc, lid), var in f2.items()
                      if mm == m and cc == chem and lane_by_id[lid]["to"] == t)
            vout = sum(getval(var) for (mm, cc, lid), var in f3.items()
                       if mm == m and cc == chem and lane_by_id[lid]["from"] == t)
            if abs(vin - vout) > 1e-4:
                ok = False
                print(f"CONSERVATION TEST FAIL {t} {m} {chem}: in={vin} out={vout}")
print("Flow conservation OK" if ok else "Flow conservation FAILED")

# Lane capacity check
ok = True
for l in lanes_m2h:
    s = sum(getval(var) for (m, chem, lid), var in f1.items() if lid == l["id"])
    if s > l["cap"] + 1e-4:
        ok = False
        print(f"LANE FAIL {l['id']}: {s} > {l['cap']}")
for l in lanes_h2t:
    s = sum(getval(var) for (m, chem, lid), var in f2.items() if lid == l["id"])
    if s > l["cap"] + 1e-4:
        ok = False
        print(f"LANE FAIL {l['id']}: {s} > {l['cap']}")
for l in lanes_t2o:
    s = sum(getval(var) for (m, chem, lid), var in f3.items() if lid == l["id"])
    if s > l["cap"] + 1e-4:
        ok = False
        print(f"LANE FAIL {l['id']}: {s} > {l['cap']}")
print("Lane capacities OK" if ok else "Lane capacities FAILED")

# Outlet TOTAL capacity check (both chemistries)
ok = True
for o in OUTLETS:
    s = sum(getval(var) for (m, cc, lid), var in f3.items() if lane_by_id[lid]["to"] == o)
    if s > outlets[o]["cap"] + 1e-4:
        ok = False
        print(f"OUTLET CAP FAIL {o}: {s} > {outlets[o]['cap']}")
print("Outlet total capacities OK" if ok else "Outlet total capacities FAILED")

# Opened facility min/max throughput
ok = True
for c in HUBS:
    s = sum(getval(var) for (m, chem, lid), var in f1.items() if lane_by_id[lid]["to"] == c)
    if getval(y[c]) > 0.5:
        if s < hubs[c]["min"] - 1e-4 or s > hubs[c]["cap"] + 1e-4:
            ok = False
            print(f"HUB THROUGHPUT FAIL {c}: {s} not in [{hubs[c]['min']},{hubs[c]['cap']}]")
for t in TESTS:
    s = sum(getval(var) for (m, chem, lid), var in f2.items() if lane_by_id[lid]["to"] == t)
    if getval(z[t]) > 0.5:
        if s < tests[t]["min"] - 1e-4 or s > tests[t]["cap"] + 1e-4:
            ok = False
            print(f"TEST THROUGHPUT FAIL {t}: {s} not in [{tests[t]['min']},{tests[t]['cap']}]")
print("Facility throughputs OK" if ok else "Facility throughputs FAILED")

# Policy check
ok = True
for chem in CHEMS:
    p = policy[chem]
    total_c = sum(markets[m][chem] for m in MARKETS)
    hv = sum(getval(var) for (m, cc, lid), var in f3.items()
             if cc == chem and lane_by_id[lid]["to"] in hv_outlets)
    sl = sum(getval(var) for (m, cc, lid), var in f3.items()
             if cc == chem and lane_by_id[lid]["to"] in sl_outlets)
    rec = sum(getval(var) for (m, cc, lid), var in f3.items()
              if cc == chem and lane_by_id[lid]["to"] in recycler_outlets)
    disp = sum(getval(var) for (m, cc, lid), var in f3.items()
               if cc == chem and lane_by_id[lid]["to"] in disp_outlets)
    hydro = sum(getval(var) for (m, cc, lid), var in f3.items()
                if cc == chem and lane_by_id[lid]["to"] in hydro_outlets)
    pyro = sum(getval(var) for (m, cc, lid), var in f3.items()
               if cc == chem and lane_by_id[lid]["to"] in pyro_outlets)
    checks = [
        ("hv", hv >= p["hv"] * total_c - 1e-4),
        ("sl", sl >= p["sl"] * total_c - 1e-4),
        ("rec", rec >= p["rec"] * total_c - 1e-4),
        ("disp", disp <= p["disp"] * total_c + 1e-4),
        ("hydro", hydro >= p["hydro"] * total_c - 1e-4),
        ("pyro", pyro <= p["pyro"] * rec + 1e-4),
    ]
    for name, good in checks:
        if not good:
            ok = False
            print(f"POLICY FAIL {chem} {name}")
    print(f"  {chem}: hydro share of total = {hydro / total_c:.6f} (floor {p['hydro']})")
print("Policy shares OK" if ok else "Policy shares FAILED")

# Carbon check
em = sum(coef * getval(var) for (coef, var) in emission_terms)
print(f"Total carbon: {em:.4f} (cap {CARBON_CAP}) -> {'OK' if em <= CARBON_CAP + 1e-4 else 'FAIL'}")

model.free()
print("Solution written to", sol_path)
